"""Validate the v5 image output contract used by provider adapters."""

from __future__ import annotations

import math
import re
from typing import Any, Callable


def canonical_ratio(value: Any, fail: Callable[[str], Exception]) -> str:
    if not isinstance(value, str):
        raise fail("request.output.aspect_ratio must use W:H")
    match = re.fullmatch(r"([1-9][0-9]*):([1-9][0-9]*)", value.strip())
    if match is None:
        raise fail("request.output.aspect_ratio must use positive integers as W:H")
    width, height = (int(item) for item in match.groups())
    divisor = math.gcd(width, height)
    return f"{width // divisor}:{height // divisor}"


def parse_output(spec: dict[str, Any], fail: Callable[[str], Exception]) -> dict[str, Any]:
    value = spec.get("output")
    if not isinstance(value, dict):
        raise fail("request.output must be a v5 output object")
    if set(value) != {"format", "aspect_ratio", "resolution"}:
        raise fail("request.output must contain exactly format, aspect_ratio, and resolution")
    if value.get("format") != "png":
        raise fail("request.output.format must be png")
    ratio = canonical_ratio(value.get("aspect_ratio"), fail)
    resolution = value.get("resolution")
    if not isinstance(resolution, dict):
        raise fail("request.output.resolution must be an object")
    mode = resolution.get("mode")
    if mode == "auto":
        if set(resolution) != {"mode", "recommended"}:
            raise fail("automatic resolution must contain exactly mode and recommended")
        recommended = resolution.get("recommended")
        if recommended is not None and not re.fullmatch(
            r"[1-9][0-9]*x[1-9][0-9]*", str(recommended)
        ):
            raise fail("request.output.resolution.recommended must use WIDTHxHEIGHT or null")
        if recommended is not None:
            width, height = dimensions(str(recommended))
            if canonical_ratio(f"{width}:{height}", fail) != ratio:
                raise fail(
                    "request.output.resolution.recommended does not match aspect_ratio"
                )
        normalized_resolution = {"mode": "auto", "recommended": recommended}
    elif mode == "explicit":
        if set(resolution) != {"mode", "width", "height"}:
            raise fail("explicit resolution must contain exactly mode, width, and height")
        width = resolution.get("width")
        height = resolution.get("height")
        if (
            isinstance(width, bool)
            or isinstance(height, bool)
            or not isinstance(width, int)
            or not isinstance(height, int)
            or width <= 0
            or height <= 0
        ):
            raise fail("explicit resolution requires positive integer width and height")
        expected = canonical_ratio(f"{width}:{height}", fail)
        if ratio != expected:
            raise fail("request.output.aspect_ratio does not match explicit resolution")
        normalized_resolution = {"mode": "explicit", "width": width, "height": height}
    else:
        raise fail("request.output.resolution.mode must be auto or explicit")
    return {"format": "png", "aspect_ratio": ratio, "resolution": normalized_resolution}


def dimensions(value: str) -> tuple[int, int]:
    width, height = value.split("x", 1)
    return int(width), int(height)

#!/usr/bin/env python3
"""Build the deterministic machine-readable catalog for bundled assets."""

from __future__ import annotations

import hashlib
import json
import os
import tempfile
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
ASSETS = ROOT / "assets"
FORM_AUTHORITY = ROOT / "references" / "form-authority.json"
OUTPUT = ROOT / "references" / "asset-catalog.json"
ALLOWED = {".png", ".jpg", ".jpeg", ".webp", ".md"}
FORM_ORDER = ("standard", "compact", "semi-chibi", "chibi", "super-deformed")


def digest(path: Path) -> str:
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            value.update(chunk)
    return value.hexdigest()


def classify(relative: Path) -> tuple[str, str | None]:
    parts = relative.parts
    category = parts[0]
    if category == "character-references":
        return "character", parts[1]
    if category == "comic-references":
        return "comic", None
    if category == "text-style-templates":
        return "text-style", parts[1]
    if category == "supporting-character-references":
        return "supporting-character", None
    raise ValueError(f"Unexpected asset category: {relative}")


def load_character_forms() -> dict[str, dict[str, object]]:
    value = json.loads(FORM_AUTHORITY.read_text(encoding="utf-8"))
    forms = value.get("character_forms")
    if set(value) != {"schema_version", "character_forms"}:
        raise ValueError("form-authority.json contains unsupported fields")
    if value.get("schema_version") != 1 or not isinstance(forms, dict):
        raise ValueError("form-authority.json must use schema_version 1")
    if tuple(forms) != FORM_ORDER:
        raise ValueError("form-authority.json must define all five forms in order")

    actual = {
        path.relative_to(ASSETS / "character-references").as_posix()
        for path in (ASSETS / "character-references").glob("*/*.webp")
    }
    if len(actual) != 15 or any(path.split("/", 1)[0] not in FORM_ORDER for path in actual):
        raise ValueError("character references must contain exactly three images for each form")
    normalized = {}
    for form, profile in forms.items():
        if not isinstance(profile, dict):
            raise ValueError(f"character form {form} must be an object")
        primary = profile.get("primary")
        mean = profile.get("mean_head_ratio")
        acceptance = profile.get("acceptance_range")
        if (
            not isinstance(primary, str)
            or not primary.startswith(f"{form}/")
            or primary not in actual
            or isinstance(mean, bool)
            or not isinstance(mean, (int, float))
            or not isinstance(acceptance, list)
            or len(acceptance) != 2
            or any(isinstance(item, bool) or not isinstance(item, (int, float)) for item in acceptance)
            or not acceptance[0] <= mean <= acceptance[1]
        ):
            raise ValueError(f"character form {form} has invalid authority metadata")
        form_paths = {path for path in actual if path.startswith(f"{form}/")}
        if len(form_paths) != 3:
            raise ValueError(f"character form {form} must contain exactly three references")
        normalized[form] = {
            "primary": f"assets/character-references/{primary}",
            "mean_head_ratio": mean,
            "acceptance_range": acceptance,
        }
    return normalized


def main() -> int:
    character_forms = load_character_forms()
    entries = []
    for path in sorted(item for item in ASSETS.rglob("*") if item.is_file()):
        if path.suffix.lower() not in ALLOWED:
            continue
        relative = path.relative_to(ASSETS)
        kind, variant = classify(relative)
        entries.append(
            {
                "path": (Path("assets") / relative).as_posix(),
                "kind": kind,
                "variant": variant,
                "sha256": digest(path),
            }
        )
    value = {
        "schema_version": 3,
        "asset_count": len(entries),
        "character_forms": character_forms,
        "assets": entries,
    }
    fd, temporary = tempfile.mkstemp(prefix=".asset-catalog.", dir=OUTPUT.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(value, handle, ensure_ascii=False, indent=2)
            handle.write("\n")
        os.replace(temporary, OUTPUT)
    except Exception:
        Path(temporary).unlink(missing_ok=True)
        raise
    print(json.dumps({"output": str(OUTPUT), "asset_count": len(entries)}, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Validate comic PNG format, dimensions, colorspace, and alpha state."""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Any


class ValidationError(RuntimeError):
    pass


def inspect(path: Path) -> dict[str, Any]:
    executable = shutil.which("magick")
    if not executable:
        raise ValidationError("ImageMagick 'magick' is required")
    try:
        result = subprocess.run(
            [executable, "identify", "-quiet", "-format", "%m|%w|%h|%[colorspace]|%[channels]", str(path)],
            check=True,
            capture_output=True,
            text=True,
            timeout=30,
        )
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired) as exc:
        raise ValidationError((getattr(exc, "stderr", "") or str(exc)).strip()) from exc
    parts = result.stdout.strip().split("|", 4)
    if len(parts) != 5:
        raise ValidationError(f"Unexpected identify output: {result.stdout.strip()}")
    return {
        "format": parts[0],
        "width": int(parts[1]),
        "height": int(parts[2]),
        "colorspace": parts[3],
        "channels": parts[4],
    }


def canonical_ratio(value: Any) -> str:
    if not isinstance(value, str):
        raise ValidationError("aspect_ratio must use positive integers as W:H")
    match = re.fullmatch(r"([1-9][0-9]*):([1-9][0-9]*)", value.strip())
    if match is None:
        raise ValidationError("aspect_ratio must use positive integers as W:H")
    width, height = (int(item) for item in match.groups())
    divisor = math.gcd(width, height)
    return f"{width // divisor}:{height // divisor}"


def normalize_output(value: dict[str, Any] | None) -> dict[str, Any]:
    if value is None:
        return {
            "format": "png",
            "aspect_ratio": "1:1",
            "resolution": {"mode": "auto", "recommended": "1024x1024"},
        }
    if (
        not isinstance(value, dict)
        or set(value) != {"format", "aspect_ratio", "resolution"}
        or value.get("format") != "png"
    ):
        raise ValidationError("output must be a PNG v5 output object")
    ratio = canonical_ratio(value.get("aspect_ratio"))
    resolution = value.get("resolution")
    if not isinstance(resolution, dict):
        raise ValidationError("output.resolution must be an object")
    mode = resolution.get("mode")
    if mode == "auto":
        if set(resolution) != {"mode", "recommended"}:
            raise ValidationError("automatic resolution requires mode and recommended")
        recommended = resolution.get("recommended")
        if recommended is not None:
            match = re.fullmatch(r"([1-9][0-9]*)x([1-9][0-9]*)", str(recommended))
            if match is None:
                raise ValidationError("recommended resolution must use WIDTHxHEIGHT or null")
            width, height = (int(item) for item in match.groups())
            if canonical_ratio(f"{width}:{height}") != ratio:
                raise ValidationError("recommended resolution does not match aspect_ratio")
        normalized_resolution = {
            "mode": "auto",
            "recommended": recommended,
        }
    elif mode == "explicit":
        if set(resolution) != {"mode", "width", "height"}:
            raise ValidationError("explicit resolution requires mode, width, and height")
        width = resolution.get("width")
        height = resolution.get("height")
        if (
            isinstance(width, bool)
            or isinstance(height, bool)
            or not isinstance(width, int)
            or not isinstance(height, int)
            or width <= 0
            or height <= 0
        ):
            raise ValidationError("explicit output requires positive width and height")
        if canonical_ratio(f"{width}:{height}") != ratio:
            raise ValidationError("aspect_ratio does not match explicit resolution")
        normalized_resolution = {"mode": "explicit", "width": width, "height": height}
    else:
        raise ValidationError("resolution.mode must be auto or explicit")
    return {"format": "png", "aspect_ratio": ratio, "resolution": normalized_resolution}


def ratio_matches(width: int, height: int, ratio: str) -> bool:
    ratio_width, ratio_height = (int(item) for item in ratio.split(":"))
    if ratio_width == ratio_height:
        return width == height
    return math.isclose(width / height, ratio_width / ratio_height, rel_tol=0.02)


def validate(path: Path, output: dict[str, Any] | None = None) -> dict[str, Any]:
    if not path.is_file() or path.read_bytes()[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValidationError("Image must be a decodable PNG file")
    expected = normalize_output(output)
    metadata = inspect(path)
    channels = metadata["channels"].lower().replace(" ", "")
    has_alpha = "alpha" in channels or channels.startswith(("rgba", "srgba", "graya", "cmyka"))
    resolution = expected["resolution"]
    if resolution["mode"] == "explicit":
        dimensions_pass = (
            metadata["width"] == resolution["width"]
            and metadata["height"] == resolution["height"]
        )
        dimensions_expected = f"exactly {resolution['width']}x{resolution['height']}"
    else:
        dimensions_pass = ratio_matches(
            metadata["width"], metadata["height"], expected["aspect_ratio"]
        )
        dimensions_expected = f"aspect ratio {expected['aspect_ratio']} at provider-native resolution"
    gates = {
        "F1": {
            "verdict": "PASS" if metadata["format"].upper() == "PNG" and dimensions_pass else "FAIL",
            "detail": f"{metadata['format']} {metadata['width']}x{metadata['height']}; expected PNG {dimensions_expected}",
        },
        "F2": {
            "verdict": "PASS" if metadata["colorspace"].lower() in {"rgb", "srgb"} and not has_alpha else "FAIL",
            "detail": f"colorspace={metadata['colorspace']}, channels={metadata['channels']}",
        },
    }
    return {
        "schema_version": 2,
        "path": str(path.resolve()),
        "candidate_sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
        "expected_output": expected,
        "overall": "PASS" if all(item["verdict"] == "PASS" for item in gates.values()) else "FAIL",
        "gates": gates,
        "metrics": metadata,
    }


def write_json(path: Path, value: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(value, handle, ensure_ascii=False, indent=2)
            handle.write("\n")
        os.replace(temporary, path)
    except Exception:
        Path(temporary).unlink(missing_ok=True)
        raise


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("image")
    parser.add_argument("--resolution-mode", choices=("auto", "explicit"), default="auto")
    parser.add_argument("--aspect-ratio", default="1:1")
    parser.add_argument("--width", type=int)
    parser.add_argument("--height", type=int)
    recommendation = parser.add_mutually_exclusive_group()
    recommendation.add_argument("--recommended")
    recommendation.add_argument("--no-recommendation", action="store_true")
    parser.add_argument("--write-json")
    args = parser.parse_args()
    try:
        if args.resolution_mode == "explicit":
            if args.width is None or args.height is None:
                raise ValidationError("explicit mode requires --width and --height")
            if args.recommended is not None or args.no_recommendation:
                raise ValidationError("recommendation flags require automatic mode")
            resolution = {
                "mode": "explicit",
                "width": args.width,
                "height": args.height,
            }
        else:
            if args.width is not None or args.height is not None:
                raise ValidationError("--width and --height require explicit mode")
            recommended = None if args.no_recommendation else args.recommended
            if (
                recommended is None
                and not args.no_recommendation
                and canonical_ratio(args.aspect_ratio) == "1:1"
            ):
                recommended = "1024x1024"
            resolution = {"mode": "auto", "recommended": recommended}
        output = {
            "format": "png",
            "aspect_ratio": args.aspect_ratio,
            "resolution": resolution,
        }
        result = validate(Path(args.image).resolve(), output)
        if args.write_json:
            write_json(Path(args.write_json).resolve(), result)
    except ValidationError as exc:
        print(json.dumps({"ok": False, "error": str(exc)}, ensure_ascii=False), file=sys.stderr)
        return 2
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0 if result["overall"] == "PASS" else 1


if __name__ == "__main__":
    raise SystemExit(main())
